def resolve_mailbox(roots, requested, preferred_root=None):
    wanted = norm(requested)
    candidates = []
    inventory = []
    ordered_roots = list(roots)
    if preferred_root is not None:
        ordered_roots.sort(key=lambda item: 0 if item == preferred_root else 1)
