class ThunderbirdRN2041TripCorrespondenceEvaluator(BaseEvaluator):
    """Judge final sent/draft mail state without operating Thunderbird's GUI."""

    @staticmethod
    def _parse_runtime_json(result: Mapping[str, Any]) -> dict[str, Any]:
        raw = result.get("stdout") or result.get("output") or ""
        try:
            payload = json.loads(raw)
        except Exception as exc:
            raise ValueError(f"mail scan returned non-JSON output: {raw!r}") from exc
        if not isinstance(payload, dict):
            raise TypeError("mail scan must return a JSON object")
        return payload

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        controller = context.get("controller")
        params = dict(context.get("params") or {})
        if controller is None or not hasattr(controller, "run_python_script"):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="controller.run_python_script is required",
                metadata={
                    "checks": [],
                    "observed_state": {},
                    "failure_reasons": ["controller.run_python_script is required"],
                    "guest_state_modified": False,
                },
            )
        if not params.get("sent_messages") or not params.get("draft_messages"):
            return EvalResult(
                status=EvalStatus.ERROR,
                message="evaluation requires sent_messages and draft_messages params",
                metadata={
                    "checks": [],
                    "observed_state": {},
                    "failure_reasons": ["sent_messages or draft_messages is empty"],
                    "guest_state_modified": False,
                },
            )

        script = dedent(_READ_ONLY_MAIL_SCAN).replace(
            "__PARAMS_JSON__", repr(json.dumps(params, ensure_ascii=False))
        )
        try:
            result = controller.run_python_script(
                script, timeout=int(params.get("timeout", 60) or 60)
            )
            payload = self._parse_runtime_json(result)
            status = {
                "pass": EvalStatus.PASS,
                "fail": EvalStatus.FAIL,
            }.get(str(payload.get("status") or "").strip().casefold(), EvalStatus.ERROR)

            final_observation = context.get("final_observation")
            foreground_app = str(
                getattr(final_observation, "foreground_app", "") or ""
            ).strip()
            foreground_bundle = str(
                getattr(final_observation, "foreground_bundle_id", "") or ""
            ).strip()
            payload["final_observation"] = {
                "foreground_app": foreground_app,
                "foreground_bundle_id": foreground_bundle,
                "used_as_business_evidence": False,
            }
            return EvalResult(
                status=status,
                message=str(payload.get("message") or "Thunderbird mail evaluation completed"),
                metadata=payload,
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.ERROR,
                message=f"Thunderbird mail evaluation failed to execute: {exc}",
                metadata={
                    "checks": [],
                    "observed_state": {},
                    "failure_reasons": [str(exc)],
                    "guest_state_modified": False,
                },
            )
